// Prepare independent local verification of the downloaded target exports.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/phase-search-c7a178";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let receipt=read(r.join("retrieval-complete.json"));assert_eq!(hash(r.join("results.tar.gz")),receipt["sha256"]);let jobs=read(r.join("remote-results/output/measure/jobs.json"));assert_eq!(jobs.as_array().unwrap().len(),120);let manifest=read(r.join("context/manifest.json"));let mut inputs=vec![];
for j in jobs.as_array().unwrap(){inputs.push((j["name"].as_str().unwrap().to_string(),j["case"].clone(),j["proof_dir"].as_str().unwrap().to_string()));}
let primary=manifest["cases"].as_array().unwrap().iter().find(|c|c["shape"]=="1x2").unwrap();for panel in["stat","cycles"]{for arm in["OFF","ON"]{inputs.push((format!("profile-{panel}-{arm}"),primary.clone(),format!("/output/profile/proofs/diagnostic-{panel}-{arm}")));}}
let mut pins=BTreeMap::new();let mut seen=BTreeSet::new();let mut steps=vec![];let verifier=r.join("context/interval-verify");pins.insert(verifier.display().to_string(),hash(&verifier));
for(name,c,dir)in inputs{let proofdir=r.join("remote-results").join(dir.strip_prefix('/').unwrap());let proof=proofdir.join("0.proof");let public=proofdir.join("0.public");let image=r.join("context/basis").join(Path::new(c["image"].as_str().unwrap()).file_name().unwrap());assert!(seen.insert(hash(&proof)));assert_eq!(hash(&public),c["public_sha256"]);assert_eq!(hash(&image),c["image_sha256"]);for p in[&proof,&public,&image]{pins.insert(p.display().to_string(),hash(p));}steps.push(json!({"kind":"command","name":name,"argv":[verifier.display().to_string(),image.display().to_string(),c["image_sha256"].as_str().unwrap().to_string(),proof.display().to_string(),public.display().to_string(),c["public_sha256"].as_str().unwrap().to_string()],"timeout_seconds":120}));}
assert_eq!(steps.len(),124);for f in["transport-review.rs","retrieval-complete.json","context/manifest.json","remote-results/output/measure/jobs.json"]{let p=r.join(f);pins.insert(p.display().to_string(),hash(p));}
assert!(!r.join("transport-pins.json").exists());fs::write(r.join("transport-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("transport-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r.join("transport-pins.json"),"steps":steps})).unwrap()).unwrap();println!("Frozen124localGnark verifications of downloaded exports; no proofgeneration");}
